#include "PipelineOrchestrator.h"
namespace dnxr { PipelineOrchestrator::PipelineOrchestrator(RuntimeConfig config) : config_(std::move(config)), mode_(runtimeModeFromString(config_.runtimeMode)) { state_.transition(PipelineState::Ready, "orchestrator constructed"); }
PipelineStepResult PipelineOrchestrator::runSyntheticCycle(std::uint64_t cycle) { if (state_.state()==PipelineState::Ready) state_.transition(PipelineState::Running, "first cycle"); profiler_.beginCycle(); PipelineStepResult result; result.step = "synthetic_cycle_" + std::to_string(cycle); if (!isSyntheticExecutionAllowed(mode_) && config_.simulationMode) { result.accepted=false; result.reason="simulation requires simulation/developer/full-unlocked mode"; state_.transition(PipelineState::Hold, result.reason); } diagnostics_.record(result); profiler_.endCycle(); return result; }
std::string PipelineOrchestrator::diagnostics() const { return diagnostics_.report() + "\n" + profiler_.report() + "\nstate=" + PipelineStateMachine::toString(state_.state()) + " reason=" + state_.lastReason(); } }
